using GravityShift.Gravity;
using GravityShift.Systems;
using Yaeger.Audio;
using Yaeger.Platform;

namespace GravityShift.Audio;

/// <summary>
/// The game's sound effects and music, played through the host's <see cref="IAudioOutput"/>
/// (OpenAL on desktop, WebAudio in the browser). The files are generated by
/// <c>tools/generate_audio.py</c> into <c>wwwroot/audio</c>.
/// </summary>
public sealed class GameSounds
{
    public const string ShiftPath = "audio/shift.wav";
    public const string LandPath = "audio/land.wav";
    public const string LockedPath = "audio/locked.wav";
    public const string ShredPath = "audio/shred.wav";
    public const string DeliverPath = "audio/deliver.wav";
    public const string LostPath = "audio/lost.wav";

    /// <summary>Ogg Vorbis; the browser falls back to music.m4a where it can't play Ogg.</summary>
    public const string MusicPath = "audio/music.ogg";

    public static readonly IReadOnlyList<string> Effects =
    [
        ShiftPath,
        LandPath,
        LockedPath,
        ShredPath,
        DeliverPath,
        LostPath,
    ];

    private readonly IAudioOutput _output;
    private readonly SoundHandle _shift;
    private readonly SoundHandle _land;
    private readonly SoundHandle _locked;
    private readonly SoundHandle _shred;
    private readonly SoundHandle _deliver;
    private readonly SoundHandle _lost;
    private readonly IMusicStream _music;

    private GameSounds(IAudioOutput output, SoundHandle[] effects)
    {
        _output = output;
        (_shift, _land, _locked, _shred, _deliver, _lost) = (
            effects[0],
            effects[1],
            effects[2],
            effects[3],
            effects[4],
            effects[5]
        );
        _music = output.OpenStream(MusicPath);
        _music.Looping = true;
        _music.Gain = Tuning.MusicGain;
    }

    /// <summary>Loads every effect and opens the music stream (stopped).</summary>
    public static async Task<GameSounds> LoadAsync(IAudioOutput output)
    {
        var effects = new SoundHandle[Effects.Count];
        for (var i = 0; i < effects.Length; i++)
            effects[i] = await output.LoadAsync(Effects[i]);
        return new GameSounds(output, effects);
    }

    public bool Muted { get; private set; }

    /// <summary>Starts the music loop. Browsers hold it until the first key press or tap.</summary>
    public void StartMusic() => _music.Play();

    public void ToggleMute()
    {
        Muted = !Muted;
        _output.Mixer.MasterVolume = Muted ? 0f : 1f;
    }

    public void Update(float deltaTime) => _output.Update(deltaTime);

    /// <summary>A whoosh, pitched by the new direction so a chain of shifts isn't monotonous.</summary>
    public void Shifted(GravityDirection direction) =>
        _output.Play(
            _shift,
            Tuning.ShiftGain,
            direction switch
            {
                GravityDirection.Down => 1f,
                GravityDirection.Left => 0.9f,
                GravityDirection.Up => 0.8f,
                _ => 1.12f,
            }
        );

    /// <summary>A soft tick when the menu selection moves.</summary>
    public void MenuMove() => _output.Play(_land, Tuning.MenuMoveGain, 1.6f);

    /// <summary>A whoosh when a menu choice is made.</summary>
    public void MenuConfirm() => _output.Play(_shift, Tuning.ShiftGain, 1.2f);

    public void ShiftLocked() => _output.Play(_locked, Tuning.LockedGain);

    /// <summary>A thud, louder the harder the parcel lands; small settles stay silent.</summary>
    public void Landed(float impactSpeed)
    {
        if (impactSpeed < Tuning.LandSoundMinSpeed)
            return;
        var strength = Math.Clamp(impactSpeed / Tuning.TerminalVelocity, 0.3f, 1f);
        _output.Play(_land, Tuning.LandGain * strength, 1.15f - 0.25f * strength);
    }

    public void LevelEnded(LevelOutcome outcome)
    {
        switch (outcome)
        {
            case LevelOutcome.Delivered:
                _output.Play(_deliver, Tuning.DeliverGain);
                break;
            case LevelOutcome.Shredded:
                _output.Play(_shred, Tuning.ShredGain);
                break;
            case LevelOutcome.Lost:
                _output.Play(_lost, Tuning.LostGain);
                break;
        }
    }
}
